package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for Frequency.getCumPct(Comparable<?> v)
 */
public class Frequency_getCumPct_TriageGen1Test {

    private static final double DELTA = 1e-15;

    @Test
    public void testGetCumPct_EmptyFrequencyReturnsNaN() {
        Frequency frequency = new Frequency();
        // sumFreq is 0, should return Double.NaN
        assertEquals(Double.NaN, frequency.getCumPct(10), DELTA);
    }

    @Test
    public void testGetCumPct_SingleValue() {
        Frequency frequency = new Frequency();
        frequency.addValue(10);
        // sumFreq = 1, getCumFreq(10) = 1. Result = 1/1 = 1.0
        assertEquals(1.0, frequency.getCumPct(10), DELTA);
    }

    @Test
    public void testGetCumPct_MultipleValues_ExactMatch() {
        Frequency frequency = new Frequency();
        frequency.addValue(10);
        frequency.addValue(20);
        frequency.addValue(30);
        frequency.addValue(30);

        // Total sumFreq = 4
        // getCumFreq(10) = 1 -> 1/4 = 0.25
        assertEquals(0.25, frequency.getCumPct(10), DELTA);

        // getCumFreq(20) = 2 -> 2/4 = 0.5
        assertEquals(0.5, frequency.getCumPct(20), DELTA);

        // getCumFreq(30) = 4 -> 4/4 = 1.0
        assertEquals(1.0, frequency.getCumPct(30), DELTA);
    }

    @Test
    public void testGetCumPct_ValueNotPresent_ReturnsZero() {
        Frequency frequency = new Frequency();
        frequency.addValue(10);
        frequency.addValue(20);

        // sumFreq = 2
        // getCumFreq(15) = 1 (assuming 10 is the only value < 15) 
        // Wait, getCumFreq logic in Frequency: returns sum of counts of values <= v
        // If 15 is not in the set, it returns count of values < 15.
        // In Frequency implementation, getCumFreq(v) returns sum of counts of all elements <= v.

        // Let's test with values that exist
        frequency.addValue(5);
        // values: 5, 10, 20. sumFreq = 3.
        // getCumFreq(5) = 1 -> 1/3
        assertEquals(1.0/3.0, frequency.getCumPct(5), DELTA);

        // getCumFreq(7) = 1 -> 1/3
        assertEquals(1.0/3.0, frequency.getCumPct(7), DELTA);
    }

    @Test
    public void testGetCumPct_StringValues() {
        Frequency frequency = new Frequency();
        frequency.addValue("apple");
        frequency.addValue("banana");
        frequency.addValue("cherry");

        // sumFreq = 3
        // "apple" -> 1/3
        assertEquals(1.0/3.0, frequency.getCumPct("apple"), DELTA);
        // "banana" -> 2/3
        assertEquals(2.0/3.0, frequency.getCumPct("banana"), DELTA);
        // "date" (not present but > cherry) -> 3/3
        assertEquals(1.0, frequency.getCumPct("date"), DELTA);
        // "aardvark" (not present and < apple) -> 0/3
        assertEquals(0.0, frequency.getCumPct("aardvark"), DELTA);
    }

    @Test
    public void testGetCumPct_AfterClear() {
        Frequency frequency = new Frequency();
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.clear();

        // sumFreq is now 0
        assertEquals(Double.NaN, frequency.getCumPct(1), DELTA);
    }
}
